  "components": [
    {
      "html": "<style>
  :root {
    --color-deep-cosmos: #201547;
    --color-violet-mid: #5938b7;
    --color-lavender-pulse: #a98df6;
    --color-graphite: #1b1b1b;
    --color-pure-white: #ffffff;
    --color-warm-cream: #fffbf4;
    --color-slate: #5f5f5f;
    --color-bone: #dbdbdb;
    --font-bagosscondensedfont: 'Inter', sans-serif;
    --font-bagossstandardvf: 'Inter', sans-serif;
    --font-inter: 'Inter', sans-serif;
  }

  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

  .hero-panel {
    background: var(--color-deep-cosmos);
    border-radius: 24px;
    padding: 48px;
    width: 100%;
    box-sizing: border-box;
    font-family: var(--font-inter);
  }

  .hero-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(255,255,255,0.08);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 200px;
    padding: 6px 14px 6px 10px;
    margin-bottom: 28px;
  }

  .hero-eyebrow-dot {
    width: 20px;
    height: 20px;
    background: var(--color-violet-mid);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }

  .hero-eyebrow-dot svg {
    width: 10px;
    height: 10px;
  }

  .hero-eyebrow-text {
    font-family: var(--font-inter);
    font-size: 13px;
    font-weight: 500;
    color: rgba(255,255,255,0.85);
    letter-spacing: 0.01em;
  }

  .hero-eyebrow-arrow {
    margin-left: 4px;
    color: rgba(255,255,255,0.5);
    font-size: 13px;
  }

  .hero-headline {
    font-family: var(--font-bagosscondensedfont);
    font-size: 56px;
    font-weight: 700;
    line-height: 1.05;
    letter-spacing: -0.005em;
    color: var(--color-pure-white);
    margin: 0 0 12px 0;
  }

  .hero-headline-accent {
    color: var(--color-lavender-pulse);
  }

  .hero-subtext {
    font-family: var(--font-inter);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.6;
    color: rgba(255,255,255,0.65);
    margin: 0 0 36px 0;
    max-width: 360px;
  }

  .hero-cta-row {
    display: flex;
    align-items: center;
    gap: 16px;
    flex-wrap: wrap;
  }

  .btn-primary {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: var(--color-violet-mid);
    color: var(--color-pure-white);
    font-family: var(--font-inter);
    font-size: 15px;
    font-weight: 500;
    letter-spacing: 0.025em;
    padding: 12px 22px;
    border-radius: 200px;
    border: none;
    cursor: pointer;
    text-decoration: none;
    transition: background 0.18s;
  }

  .btn-primary:hover {
    background: #6a44cc;
  }

  .btn-primary svg {
    width: 14px;
    height: 14px;
    flex-shrink: 0;
  }

  .btn-ghost-dark {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: transparent;
    color: rgba(255,255,255,0.75);
    font-family: var(--font-inter);
    font-size: 15px;
    font-weight: 500;
    letter-spacing: 0.025em;
    padding: 12px 4px;
    border-radius: 0;
    border: none;
    cursor: pointer;
    text-decoration: none;
    transition: color 0.18s;
  }

  .btn-ghost-dark:hover {
    color: var(--color-pure-white);
  }
</style>
<div class="hero-panel">
  <div class="hero-eyebrow">
